"""A basic text-based adventure game with rooms and items."""

import sys

ROOMS = {
    "entrance": {
        "description": "You stand in the entrance hall of an old stone building. Cobwebs hang from the ceiling. A wooden door leads north.",
        "exits": {"north": "hallway"},
        "items": ["lantern"],
    },
    "hallway": {
        "description": "A long hallway stretches before you. Paintings of stern faces line the walls. Doors lead south, east, and west.",
        "exits": {"south": "entrance", "east": "library", "west": "kitchen"},
        "items": [],
    },
    "library": {
        "description": "Towering bookshelves fill every wall. The air smells of old paper and dust. A heavy tome sits on a reading desk.",
        "exits": {"west": "hallway", "north": "study"},
        "items": ["tome"],
    },
    "study": {
        "description": "A cozy study with a crackling fireplace. A locked chest sits in the corner.",
        "exits": {"south": "library"},
        "items": ["key"],
    },
    "kitchen": {
        "description": "An old kitchen with a large hearth. Pots and pans hang from hooks. A passage leads north to the cellar.",
        "exits": {"east": "hallway", "north": "cellar"},
        "items": ["bread"],
    },
    "cellar": {
        "description": "A damp cellar lit by phosphorescent fungi on the walls. A treasure chest gleams in the corner.",
        "exits": {"south": "kitchen"},
        "items": ["treasure"],
    },
}

player = {
    "room": "entrance",
    "inventory": [],
}

WIN_CONDITION_ITEMS = {"tome", "key", "treasure"}


def describe_room():
    room = ROOMS[player["room"]]
    print(f"\n--- {player['room'].upper()} ---")
    print(room["description"])
    if room["items"]:
        print(f"You see: {', '.join(room['items'])}")
    exits = ", ".join(room["exits"].keys())
    print(f"Exits: {exits}")


def move(direction):
    room = ROOMS[player["room"]]
    if direction in room["exits"]:
        player["room"] = room["exits"][direction]
        describe_room()
    else:
        print("You can't go that way.")


def take(item):
    room = ROOMS[player["room"]]
    if item in room["items"]:
        room["items"].remove(item)
        player["inventory"].append(item)
        print(f"You pick up the {item}.")
    else:
        print(f"There's no {item} here.")


def drop(item):
    if item in player["inventory"]:
        player["inventory"].remove(item)
        ROOMS[player["room"]]["items"].append(item)
        print(f"You drop the {item}.")
    else:
        print(f"You don't have a {item}.")


def show_inventory():
    if player["inventory"]:
        print(f"Inventory: {', '.join(player['inventory'])}")
    else:
        print("Your inventory is empty.")


def check_win():
    if WIN_CONDITION_ITEMS.issubset(set(player["inventory"])):
        print("\nAs you place the tome, key, and treasure together, the wall slides open!")
        print("You've found the secret passage and escaped. Congratulations, you win!")
        return True
    return False


def show_help():
    print("\nCommands:")
    print("  go <direction>   - Move in a direction (north/south/east/west)")
    print("  take <item>      - Pick up an item")
    print("  drop <item>      - Drop an item")
    print("  inventory / i    - Show your inventory")
    print("  look             - Describe the current room")
    print("  help             - Show this help message")
    print("  quit             - Exit the game")


def main():
    print("=" * 50)
    print("  THE FORGOTTEN MANOR")
    print("=" * 50)
    print("\nYou wake up in a strange old building.")
    print("Collect the tome, key, and treasure to unlock the secret exit.")
    print("Type 'help' for a list of commands.\n")

    describe_room()

    while True:
        try:
            raw = input("\n> ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print("\nGoodbye!")
            break

        if not raw:
            continue

        parts = raw.split(maxsplit=1)
        command = parts[0]
        arg = parts[1] if len(parts) > 1 else ""

        if command in ("go", "move", "walk"):
            if arg:
                move(arg)
            else:
                print("Go where? (e.g. 'go north')")
        elif command in ("n", "north"):
            move("north")
        elif command in ("s", "south"):
            move("south")
        elif command in ("e", "east"):
            move("east")
        elif command in ("w", "west"):
            move("west")
        elif command == "take" or command == "get":
            if arg:
                take(arg)
            else:
                print("Take what?")
        elif command == "drop":
            if arg:
                drop(arg)
            else:
                print("Drop what?")
        elif command in ("inventory", "i"):
            show_inventory()
        elif command == "look":
            describe_room()
        elif command == "help":
            show_help()
        elif command in ("quit", "exit", "q"):
            print("Goodbye!")
            break
        else:
            print("Unknown command. Type 'help' for a list of commands.")

        if check_win():
            break


if __name__ == "__main__":
    main()
